export function getPrecomputedNovidades(key?: string): ModItem[] | null {
  if (!key) return null;
  const k = key.toLowerCase().trim();
  if (NOVIDADES_BY_SLUG[k]) return NOVIDADES_BY_SLUG[k];

  const targetFromId = ID_TO_SLUG[k];
  if (targetFromId && NOVIDADES_BY_SLUG[targetFromId]) return NOVIDADES_BY_SLUG[targetFromId];

  const targetFromAlias = ALIAS_TO_SLUG[k];
  if (targetFromAlias && NOVIDADES_BY_SLUG[targetFromAlias]) return NOVIDADES_BY_SLUG[targetFromAlias];

  // Try matching stripped key (e.g., removing prefixes or dashes)
  const simplified = k.replace(/[_-]/g, '');
  for (const [slug, items] of Object.entries(NOVIDADES_BY_SLUG)) {
    if (slug.replace(/[_-]/g, '') === simplified) return items;
  }

  return null;
}

export const NOVIDADES_PRONTAS: Record<string, ModItem[]> = new Proxy(NOVIDADES_BY_SLUG, {
  get(target, prop: string) {
    if (typeof prop !== 'string') return undefined;
    return getPrecomputedNovidades(prop) || target[prop];
  }
});
